    public static IReadOnlyList<SkillIconSeedDefinition> Icons { get; } = ExpandIcons();

    private static IReadOnlyList<SkillIconSeedDefinition> ExpandIcons()
    {
        var sourceIconsBySkill = SourceIcons
            .GroupBy(icon => icon.SkillId)
            .ToDictionary(group => group.Key, group => group.ToArray());
        var icons = new List<SkillIconSeedDefinition>();

        foreach (var skill in Skills)
        {
            if (!sourceIconsBySkill.TryGetValue(skill.Id, out var sourceIcons))
            {
                continue;
            }

            var sharedIcon = sourceIcons.SingleOrDefault(icon => icon.Level == 0);
            if (sharedIcon is not null)
            {
                for (var level = 1; level <= skill.Levels; level++)
                {
                    icons.Add(new SkillIconSeedDefinition(skill.Id, (short)level, sharedIcon.Name));
                }

                continue;
            }

            icons.AddRange(sourceIcons);
        }

        return icons;
    }
